import { useLayoutEffect, useRef, useState } from "react";
import { TokenSearchField } from "@kerfjs/ui/token-search-field";
import "@kerfjs/ui/layout.css";

export type FilterToken = { id: string; label: string; value: string };
export type SearchValue = { text: string; tokens: FilterToken[] };
export type SearchAction = { type: "workspace.search.changed"; value: SearchValue };
type Caret = { start: number; end: number };
export function WorkspaceSearch({ value, parse, suggest, dispatch }: {
  value: SearchValue;
  parse: (text: string, tokens: FilterToken[]) => SearchValue;
  suggest: (text: string, tokens: FilterToken[]) => FilterToken[];
  dispatch: (action: SearchAction) => void;
}) {
  const host = useRef<HTMLDivElement>(null);
  const caret = useRef<Caret | null>(null);
  const [announcement, setAnnouncement] = useState("");
  const [revision, setRevision] = useState(0);
  // The application owns the domain parser, suggestion provider, and ordered value.
  const publish = (next: SearchValue) => dispatch({ type: "workspace.search.changed", value: next });
  const rememberCaret = () => {
    const input = host.current?.querySelector<HTMLInputElement>('input');
    caret.current = input ? { start: input.selectionStart ?? value.text.length, end: input.selectionEnd ?? value.text.length } : { start: value.text.length, end: value.text.length };
  };
  const restore = () => setRevision(n => n + 1);
  useLayoutEffect(() => {
    if (!caret.current) return;
    const input = host.current?.querySelector<HTMLInputElement>('input');
    if (input) {
      input.focus();
      input.setSelectionRange(Math.min(caret.current.start, input.value.length), Math.min(caret.current.end, input.value.length));
      caret.current = null;
    }
  }, [value, revision]);
  return <div ref={host} className="kui-layout">
    <TokenSearchField aria-label="Search workspace" text={value.text} tokens={value.tokens}
      suggestions={suggest(value.text, value.tokens)}
      onTextChange={(text: string) => publish({ ...value, text })}
      onCommit={() => { rememberCaret(); publish(parse(value.text, value.tokens)); restore(); }}
      onTokenRemove={(id: string) => {
        rememberCaret();
        const removed = value.tokens.find(token => token.id === id);
        publish({ ...value, tokens: value.tokens.filter(token => token.id !== id) });
        setAnnouncement(removed ? `Removed filter ${removed.label}.` : "");
        restore();
      }}
      onTokenReplace={(id: string, replacement: FilterToken) => {
        rememberCaret();
        publish({ ...value, tokens: value.tokens.map(token => token.id === id ? { ...replacement, id } : token) });
        setAnnouncement(`Filter changed to ${replacement.label}.`);
        restore();
      }}
      onSuggestionSelect={(token: FilterToken) => {
        rememberCaret();
        publish({ ...value, tokens: [...value.tokens, { ...token, id: crypto.randomUUID() }] });
        setAnnouncement(`Added filter ${token.label}.`);
        restore();
      }}
      onClear={() => {
        caret.current = { start: 0, end: 0 };
        publish({ text: "", tokens: [] });
        setAnnouncement("Search cleared.");
        restore();
      }} />
    <span role="status" aria-live="polite" aria-atomic="true">{announcement}</span>
  </div>;
}
